using System;using System.Linq;using System.IO;using System.Drawing;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;
namespace IslandIntegrated {
 public static class WebsiteLatency {
  static readonly object gate=new object();static bool running,attempted;static DateTimeOffset observed;static int count,mean;static long nextAutoMs;
  static readonly string[] targets={"https://www.google.com/generate_204","https://www.microsoft.com/","https://www.apple.com/"};
  public static string Label(DateTimeOffset now){lock(gate){if(running)return "测速中";double age=(now-observed).TotalSeconds;return count>0&&age>=-5&&age<=300?mean+" ms · "+count+"/3":"不可用";}}
  public static string Signal(DateTimeOffset now){lock(gate){double age=(now-observed).TotalSeconds;if(running||!attempted||age< -5||age>300)return "unknown";return Classify(count,mean);}}
  public static string Classify(int successes,int milliseconds){return successes<=0?"unreachable":milliseconds>300?"slow":"normal";}
  public static int? Average(int[] values){if(values==null||values.Length==0||values.Any(x=>x<=0||x>60000))return null;return (int)Math.Round(values.Average());}
  static int? Measure(string url){try{var request=(System.Net.HttpWebRequest)System.Net.WebRequest.Create(url);request.Method="HEAD";request.Timeout=4000;request.ReadWriteTimeout=4000;request.AllowAutoRedirect=false;request.KeepAlive=false;request.UseDefaultCredentials=false;var watch=System.Diagnostics.Stopwatch.StartNew();using(var response=(System.Net.HttpWebResponse)request.GetResponse()){watch.Stop();int status=(int)response.StatusCode;return status>=200&&status<400?(int?)Math.Max(1,Math.Min(60000,watch.ElapsedMilliseconds)):null;}}catch{return null;}}
  public static bool ShouldAutoStart(long nowMs,long dueMs,bool active){return !active&&nowMs>=dueMs;}
  static long MonotonicMs(){return (long)(System.Diagnostics.Stopwatch.GetTimestamp()*1000d/System.Diagnostics.Stopwatch.Frequency);}
  public static bool StartIfDue(){lock(gate){if(!ShouldAutoStart(MonotonicMs(),nextAutoMs,running))return false;}return Start();}
  public static bool Start(){lock(gate){if(running)return false;running=true;count=0;nextAutoMs=MonotonicMs()+300000;}System.Threading.Tasks.Task.Run(()=>{var values=new List<int>();try{foreach(var url in targets){var sample=Measure(url);if(sample.HasValue)values.Add(sample.Value);}}finally{lock(gate){count=values.Count;mean=Average(values.ToArray())??0;observed=DateTimeOffset.UtcNow;attempted=true;running=false;}}});return true;}
 }
 public sealed class NetworkReadonlySnapshot {
  public DateTimeOffset Timestamp,DelayTimestamp;public string MacState="unknown",MihomoState="unknown",SocksState="unknown",Group="",Current="",DelayRoute="";public int? DelayMs;public string[] Choices=new string[0];
  public string DelayLabel(DateTimeOffset now){double age=(now-DelayTimestamp).TotalSeconds;return Fresh(now)&&MihomoState=="ok"&&!String.IsNullOrEmpty(Current)&&Current==DelayRoute&&DelayMs.HasValue&&DelayMs.Value>0&&DelayMs.Value<=60000&&age>=-5&&age<=60?DelayMs.Value.ToString()+" ms":"延迟不可用";}
  public bool Fresh(DateTimeOffset now){double age=(now-Timestamp).TotalSeconds;return age>=-5&&age<=60;}
  static string S(Dictionary<string,object>d,string key){object o;return d!=null&&d.TryGetValue(key,out o)&&o is string?((string)o).Substring(0,Math.Min(200,((string)o).Length)):"";}
  public static NetworkReadonlySnapshot Parse(string raw){try{if(raw==null||raw.Length>65536)return new NetworkReadonlySnapshot();var d=new JavaScriptSerializer{MaxJsonLength=65536,RecursionLimit=8}.DeserializeObject(raw) as Dictionary<string,object>;if(d==null)return new NetworkReadonlySnapshot();var s=new NetworkReadonlySnapshot{MacState=S(d,"tailscaleState"),MihomoState=S(d,"selectorState"),Group=S(d,"selectorGroup"),Current=S(d,"currentRoute")};if(S(d,"mihomoVersionState")=="access-denied")s.MihomoState="access-denied";DateTimeOffset.TryParse(S(d,"utc"),out s.Timestamp);object value;if(d.TryGetValue("choices",out value)&&value is object[]){var names=new List<string>();foreach(var item in (object[])value){var name=item as string;if(!String.IsNullOrWhiteSpace(name)&&name.Length<=200&&!names.Contains(name)&&names.Count<128)names.Add(name);}s.Choices=names.ToArray();}return s;}catch{return new NetworkReadonlySnapshot();}}
  public static NetworkReadonlySnapshot Load(string file){try{if(String.IsNullOrEmpty(file))return new NetworkReadonlySnapshot();var f=new FileInfo(file);if(!f.Exists||f.Length>65536||(f.Attributes&FileAttributes.ReparsePoint)!=0||(f.Directory.Attributes&FileAttributes.ReparsePoint)!=0)return new NetworkReadonlySnapshot();return Parse(File.ReadAllText(file));}catch{return new NetworkReadonlySnapshot();}}
  public string RouteLabel(DateTimeOffset now){return MihomoState=="access-denied"?"\u4e0a\u6b21\u8bfb\u53d6\u53d7\u9650":!Fresh(now)?"\u72b6\u6001\u5df2\u8fc7\u671f":MihomoState=="ok"&&!String.IsNullOrEmpty(Current)?Current:"\u63a7\u5236\u7aef\u672a\u63a5\u5165";}
  public string MacLabel {get{return "\u672a\u5c55\u793a";}}
  public bool CanPreview(DateTimeOffset now){return Fresh(now)&&MihomoState=="ok"&&Choices.Length>0&&!String.IsNullOrEmpty(Group);}
 }
